def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

a, b = map(int, input().split())
primes = [n for n in range(a, b + 1) if is_prime(n)]
if primes:
    print(*primes)
else:
    print("없음")
